"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96082"],{90010(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.tipo_ato.codigo_imutavel","status":422,"titulo":"O c\xf3digo do tipo de ato \xe9 a sua identidade e n\xe3o pode ser alterado"},"descricao":{"codigo":"uniplus.publicacoes.tipo_ato.codigo_imutavel","requisitos":[],"oQueAconteceu":["A atualiza\xe7\xe3o tentou trocar o **c\xf3digo** do tipo de ato. Essa recusa s\xf3\\nexiste na atualiza\xe7\xe3o \u2014 na cria\xe7\xe3o n\xe3o h\xe1 c\xf3digo anterior para divergir.","O c\xf3digo n\xe3o \xe9 um r\xf3tulo edit\xe1vel: \xe9 a identidade do tipo. Duas coisas\\ndependem de ele n\xe3o mudar. A s\xe9rie de vig\xeancias se agrupa por ele \u2014 \xe9 o\\nc\xf3digo que a exclusion constraint do banco compara para impedir duas\\nvers\xf5es vivas no mesmo dia \u2014, ent\xe3o renomear uma vers\xe3o a desgarraria das\\ndemais, partindo o tipo em dois sem que ningu\xe9m o tivesse pedido. E a vaga\\nque um objeto reserva para uma linhagem de atos \xfanicos por objeto \xe9\\nchaveada pelo c\xf3digo: renome\xe1-lo abriria uma vaga nova no mesmo objeto, e\\no certame acabaria com dois editais de abertura vivos."],"comoResolver":["Se a inten\xe7\xe3o \xe9 corrigir a grafia do c\xf3digo, n\xe3o \xe9 uma atualiza\xe7\xe3o \u2014 \xe9 um\\ntipo novo: cadastre-o com o c\xf3digo correto e trate o antigo \xe0 parte\\n(mantenha-o se j\xe1 houver ato publicado sob ele, ou remova-o se nunca foi\\nusado). Se a inten\xe7\xe3o era s\xf3 editar nome, atributos de consequ\xeancia,\\nvig\xeancia ou base legal, reenvie a atualiza\xe7\xe3o com o c\xf3digo original,\\ninalterado."],"ondeAparece":["Atualiza\xe7\xe3o de tipo de ato"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Tipo ato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);